class Solution {
public:
    int largestRectangleArea(vector<int>& heights) {
        int n = heights.size();
        stack<int> st;
        long long maxArea = 0;
        for (int i = 0; i <= n; ++i) {
            int cur = (i == n) ? 0 : heights[i];
            while (!st.empty() && cur < heights[st.top()]) {
                int h = heights[st.top()];
                st.pop();
                int left = st.empty() ? -1 : st.top();
                long long width = i - left - 1;
                maxArea = max(maxArea, (long long)h * width);
            }
            st.push(i);
        }
        return (int)maxArea;
    }
};
